925	func opIDFor(cd *campaignDevice, phase string) string {
926		switch phase {
927		case StageInstall:
928			return cd.Install.ID
929		case StageRollback:
930			return cd.Rollback.ID
931		default:
932			return cd.Download.ID
933		}
934	}
935	
936	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
937	func pendingPhase(cd *campaignDevice) string {
938		if cd.Download.HasResult && cd.Download.Success {
939			return StageInstall
940		}
941		return StageDownload
942	}
943	
944	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
945	// 已有终态保持不变，活动记为失败并结束。等待回滚或正在回滚的设备
946	// 以回滚阶段超时结束；不改写或清空影子。
947	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
948		if c.Ended {
949			return
950		}
951		for _, cd := range c.Devices {
952			if isTerminal(cd.Status) {
953				continue
954			}
955			switch cd.Status {
956			case DeviceAwaitingRollback, DeviceRollingBack:
957				cd.Status = DeviceRollbackTimeout
958				cd.Phase = StageRollback
959			default:
960				cd.Status = DeviceTimeout
961				cd.Phase = pendingPhase(cd)
962			}
963			cd.Reason = "deadline exceeded"
964			cd.At = at
965		}
966		c.Status = CampaignFailed
967		c.Ended = true
968		c.EndedAt = at
969	}
970	
971	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
972	// 即使回滚成功，设备也不是 succeeded，活动仍为失败。
973	func (s *Store) settle(c *campaignState, at time.Time) {
974		allSucceeded := true
975		for _, cd := range c.Devices {
976			if !isTerminal(cd.Status) {
977				return
978			}
979			if cd.Status != DeviceSucceeded {
980				allSucceeded = false
981			}
982		}
983		c.Ended = true
984		c.EndedAt = at
985		if allSucceeded {
986			c.Status = CampaignSucceeded
987		} else {
988			c.Status = CampaignFailed
989		}
990	}
