1123	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
1124	// 失败或超时原因及结果历史。返回数据为独立副本。
1125	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
1126		s.mu.Lock()
1127		defer s.mu.Unlock()
1128		if err := s.checkOpen(); err != nil {
1129			return CampaignView{}, err
1130		}
1131		c, err := s.lookupCampaign(campaignID)
1132		if err != nil {
1133			return CampaignView{}, err
1134		}
1135		v := CampaignView{
1136			ID:                c.ID,
1137			Operator:          c.Operator,
1138			TargetVersion:     c.Target,
1139			CreatedAt:         c.CreatedAt,
1140			BatchSize:         c.BatchSize,
1141			WindowStart:       c.WindowStart,
1142			WindowEnd:         c.WindowEnd,
1143			Deadline:          c.Deadline,
1144			RollbackOnFailure: c.RollbackOnFailure,
1145			Status:            c.Status,
1146			Ended:             c.Ended,
1147			EndedAt:           c.EndedAt,
1148			Results:           make([]ResultRecord, len(c.Results)),
1149		}
1150		copy(v.Results, c.Results)
1151		for _, cd := range c.Devices {
1152			dv := DeviceStatusView{
1153				DeviceID:       cd.DeviceID,
1154				Batch:          cd.Batch,
1155				Status:         cd.Status,
1156				Phase:          cd.Phase,
1157				Reason:         cd.Reason,
1158				At:             cd.At,
1159				DownloadID:     cd.Download.ID,
1160				InstallID:      cd.Install.ID,
1161				RollbackID:     cd.Rollback.ID,
1162				RollbackTarget: cd.RollbackTarget,
1163			}
1164			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1165			if cd.Install.HasResult && !cd.Install.Success {
1166				dv.InstallFailReason = cd.Install.Reason
1167				dv.InstallFailAt = cd.Install.At
1168			}
1169			// 回滚结果的原因与时间单独呈现。
1170			if cd.Rollback.HasResult {
1171				dv.RollbackResult = true
1172				dv.RollbackSuccess = cd.Rollback.Success
1173				dv.RollbackReason = cd.Rollback.Reason
1174				dv.RollbackAt = cd.Rollback.At
1175			}
1176			v.Devices = append(v.Devices, dv)
1177			for len(v.Batches) <= cd.Batch {
1178				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1179			}
1180			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1181		}
1182		return v, nil
1183	}
