90		dl, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
91		if err != nil || dl == nil {
92			t.Fatalf("claim: %v %+v", err, dl)
93		}
94		if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.RollbackTarget != "v1" {
95			t.Fatalf("target locked at first download claim: %+v", d)
96		}
97		// 下载进行中普通上报把版本改成别的：锁定目标不变，也不要求该版本登记。
98		if err := s.Report("d1", 2, upBase.Add(3*time.Minute), "v9-other", json.RawMessage(`{}`)); err != nil {
99			t.Fatal(err)
100		}
101		if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.RollbackTarget != "v1" {
102			t.Fatalf("plain report changed locked target: %+v", d)
103		}
104		if st := deviceStatus(mustGetCampaign(s, spec.ID), "d1"); st != DeviceDownloading {
105			t.Fatalf("plain report must not advance campaign: %s", st)
106		}
