109	// 安装失败进入等待回滚：保留原因/时间；同批继续、后续批次立即 skipped；
110	// 活动要等回滚设备结束；即使回滚成功，活动最终仍失败。
111	func TestInstallFailureAwaitsRollbackAndCascades(t *testing.T) {
112		s := setupUpgrade(t, "d1", "d2", "d3")
113		spec := upSpec()
114		spec.Devices = []string{"d1", "d2", "d3"}
115		spec.BatchSize = 2
116		spec.RollbackOnFailure = true
117		createCampaign(t, s, spec)
118		for _, id := range spec.Devices {
119			bringOnline(t, s, id)
120		}
121	
122		_, failAt := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
123		v, _ := s.GetCampaign(spec.ID)
124		d1 := findDevice(v, "d1")
125		if d1.Status != DeviceAwaitingRollback || d1.Phase != StageRollback {
126			t.Fatalf("d1 should await rollback: %+v", d1)
127		}
128		if d1.InstallFailReason != "install broken" || !d1.InstallFailAt.Equal(failAt) {
129			t.Fatalf("install failure reason/time kept: %+v", d1)
130		}
131		if v.Ended {
132			t.Fatal("campaign must wait for rollback device")
133		}
134		if st := deviceStatus(v, "d3"); st != DeviceSkipped {
135			t.Fatalf("later batch skipped at once: %s", st)
136		}
137		// 等待回滚的设备不能参加其他活动。
138		other := spec
139		other.ID = "cmp-other"
140		other.CreatedAt = upBase.Add(time.Minute)
141		other.Devices = []string{"d1"}
142		if err := s.CreateCampaign(other); !errors.Is(err, ErrDeviceBusy) {
143			t.Fatalf("awaiting device busy: %v", err)
144		}
145	
146		// 同批 d2 可继续成功；活动仍因 d1 未结束而运行。
147		finishDevice(t, s, spec, "d2", upBase.Add(10*time.Minute))
148		if v, _ = s.GetCampaign(spec.ID); v.Ended {
149			t.Fatal("campaign still waits for d1 rollback")
150		}
151	
152		// d1 领取并完成回滚（窗口外、截止前提交）。
153		rb, err := s.Claim(spec.ID, "d1", upBase.Add(20*time.Minute))
154		if err != nil || rb == nil || rb.Kind != StageRollback || rb.TargetVersion != "v1" {
155			t.Fatalf("claim rollback: %v %+v", err, rb)
156		}
157		if err := s.SubmitResult(OperationResult{
158			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
159			At: upBase.Add(90 * time.Minute), Success: true,
160			Seq: 2, Version: "v1", Config: json.RawMessage(`{"rollback":true}`),
161		}); err != nil {
162			t.Fatalf("rollback result: %v", err)
163		}
164		v, _ = s.GetCampaign(spec.ID)
165		d1 = findDevice(v, "d1")
166		if d1.Status != DeviceRollbackSucceeded {
167			t.Fatalf("rollback succeeded status: %+v", d1)
168		}
169		if !v.Ended || v.Status != CampaignFailed {
170			t.Fatalf("campaign fails even with successful rollback: %+v", v)
171		}
172	}
