504	// 到达原截止时间：等待/正在回滚的设备以回滚阶段超时结束，不改写影子；
505	// 不再接收新结果；已接受结果的重复提交仍有效。
506	func TestRollbackDeadlineTimeout(t *testing.T) {
507		s := setupUpgrade(t, "d1", "d2")
508		spec := upSpec()
509		spec.Devices = []string{"d1", "d2"}
510		spec.BatchSize = 2
511		spec.RollbackOnFailure = true
512		createCampaign(t, s, spec)
513		bringOnline(t, s, "d1")
514		bringOnline(t, s, "d2")
515	
516		// d1 领取回滚并成功；d2 安装失败后停在等待回滚。
517		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
518		rb1, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
519		rb1At := upBase.Add(9 * time.Minute)
520		if err := s.SubmitResult(OperationResult{
521			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb1.ID,
522			At: rb1At, Success: true,
523			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
524		}); err != nil {
525			t.Fatalf("d1 rollback: %v", err)
526		}
527		awaitRollback(t, s, spec, "d2", upBase.Add(12*time.Minute))
528		// d2 领取回滚但不完成（正在回滚）。
529		rb2, _ := s.Claim(spec.ID, "d2", upBase.Add(20*time.Minute))
530	
531		if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
532			t.Fatal(err)
533		}
534		v, _ := s.GetCampaign(spec.ID)
535		if !v.Ended || v.Status != CampaignFailed {
536			t.Fatalf("deadline ends campaign failed: %+v", v)
537		}
538		d2 := findDevice(v, "d2")
539		if d2.Status != DeviceRollbackTimeout || d2.Phase != StageRollback || d2.Reason == "" {
540			t.Fatalf("rolling-back device rollback-timeout: %+v", d2)
541		}
542		d1 := findDevice(v, "d1")
543		if d1.Status != DeviceRollbackSucceeded {
544			t.Fatalf("finished rollback kept: %+v", d1)
545		}
546		// 影子不被超时改写。
547		if sh, _ := s.Get("d2"); sh.Version != "v1" || sh.LastSeq != 1 {
548			t.Fatalf("shadow changed on timeout: %+v", sh)
549		}
550		// 不再接收新结果。
551		if err := s.SubmitResult(OperationResult{
552			CampaignID: spec.ID, DeviceID: "d2", OperationID: rb2.ID,
553			At: upBase.Add(2*time.Hour + time.Minute), Success: true,
554			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
555		}); !errors.Is(err, ErrCampaignEnded) {
556			t.Fatalf("new rollback result after deadline: %v", err)
557		}
558		// 已接受结果的重复提交仍有效，不增加历史。
559		n := len(v.Results)
560		if err := s.SubmitResult(OperationResult{
561			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb1.ID,
562			At: upBase.Add(3 * time.Hour), Success: true,
563			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
564		}); err != nil {
565			t.Fatalf("accepted result replay after end: %v", err)
566		}
567		if cv, _ := s.GetCampaign(spec.ID); len(cv.Results) != n {
568			t.Fatal("replay after deadline added history")
569		}
570	}
