572	// 回滚未完成时的普通上报只更新影子，不替代回滚结果或清除待办；
573	// 回滚最终仍必须恢复到锁定版本。
574	func TestPlainReportDuringRollbackOnlyUpdatesShadow(t *testing.T) {
575		s := setupUpgrade(t, "d1")
576		spec := rbSpec()
