582		if err := s.Report("d1", 2, upBase.Add(6*time.Minute), "v-stray", json.RawMessage(`{"a":1}`)); err != nil {
583			t.Fatal(err)
584		}
585		if sh, _ := s.Get("d1"); sh.Version != "v-stray" || sh.LastSeq != 2 {
586			t.Fatalf("plain report should update shadow: %+v", sh)
