594		if w.Pending == nil || w.Pending.Kind != StageRollback || w.PendingClaimed ||
595			w.Pending.TargetVersion != "v1" {
596			t.Fatalf("rollback todo survives plain report: %+v", w)
597		}
598		// 回滚成功以更大序号、锁定版本 v1 接受：影子回到锁定版本与上报配置。
599		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
