603			Seq: 3, Version: "v1", Config: json.RawMessage(`{"a":0}`),
604		}); err != nil {
605			t.Fatalf("rollback to locked target: %v", err)
606		}
607		if sh, _ := s.Get("d1"); sh.Version != "v1" || sh.LastSeq != 3 || string(sh.Reported) != `{"a":0}` {
608			t.Fatalf("shadow restored to locked target: %+v", sh)
609		}
