	if d.Status != DeviceFailed || d.Phase != StageInstall {
		t.Fatalf("legacy install failure: %+v", d)
	}
	if d.RollbackTarget != "" || d.RollbackResult {
		t.Fatalf("legacy failure must not carry rollback state: %+v", d)
	}
